package com.example.salarygrows;
import android.app.*;import android.content.*;import android.os.*;import java.time.*;
public class SalaryNotifications extends BroadcastReceiver {
 static final String CHANNEL="salary_events";
 public static void schedule(Context c){AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);if(am==null)return;Intent i=new Intent(c,SalaryNotifications.class);PendingIntent pi=PendingIntent.getBroadcast(c,870,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);am.cancel(pi);long next=System.currentTimeMillis()+15*60*1000L;am.setInexactRepeating(AlarmManager.RTC_WAKEUP,next,AlarmManager.INTERVAL_HOUR,pi);}
 @Override public void onReceive(Context c,Intent i){SharedPreferences p=c.getSharedPreferences("salary",Context.MODE_PRIVATE);LocalDateTime now=LocalDateTime.now();String key=now.toLocalDate().toString();String msg=null;if(p.getBoolean("notify_pay",false)&&now.getHour()>=9&&SalaryFeatures.nextPay(p,now.toLocalDate()).equals(now.toLocalDate())&&!key.equals(p.getString("pay_notice_date",""))){msg="오늘은 월급날이에요 💵";p.edit().putString("pay_notice_date",key).apply();}if(p.getBoolean("notify_progress",false)){double f=SalaryFeatures.fraction(p,now);for(int t:new int[]{25,50,75,100}){String k="notice_"+now.getYear()+"_"+now.getMonthValue()+"_"+t;if(f*100>=t&&!p.getBoolean(k,false)){p.edit().putBoolean(k,true).apply();msg="이번 달 월급 "+t+"% 적립 달성!";break;}}}if(msg!=null){NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);if(Build.VERSION.SDK_INT>=26)nm.createNotificationChannel(new NotificationChannel(CHANNEL,"월급 알림",NotificationManager.IMPORTANCE_DEFAULT));if(Build.VERSION.SDK_INT<33||c.checkSelfPermission("android.permission.POST_NOTIFICATIONS")==android.content.pm.PackageManager.PERMISSION_GRANTED){Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,CHANNEL):new Notification.Builder(c);b.setSmallIcon(R.mipmap.ic_launcher).setContentTitle("월급이 자란다 💵").setContentText(msg).setAutoCancel(true);nm.notify(870,b.build());}}SalaryWidget.refresh(c);}
}
